#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2086,SC2295
# pre-deploy-mule-app.sh — JAR surgery: inject env.yaml / env-secure.yaml / overlay from env-settings, validate, re-JAR, extract parent GAV.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/steps/pre-deploy-mule-application.yml
#   step   : "Pre-Deploy: Transform JAR for ${{ parameters.muleEnv }}" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Inputs (environment):
#   MDF_ARTIFACTS_DIR      <- ${{ parameters.artifactsDir }}  [default: $(Pipeline.Workspace)/mule-artifacts]
#   MDF_ARTIFACT_ID        <- ${{ parameters.artifactId }}  [required]
#   MDF_BG_ID              <- ${{ parameters.bgId }}  [default: $(ANYPOINT_BG_ID)]
#   MDF_CLASSIFIER         <- ${{ parameters.classifier }}  [default: mule-application]
#   MDF_DEPLOYMENT_TARGET  <- ${{ parameters.deploymentTarget }}  [default: ch2]
#   MDF_ENV_SETTINGS_PATH  <- ${{ parameters.envSettingsPath }}  [required]
#   MDF_MULE_ENV           <- ${{ parameters.muleEnv }}  [required]
#   MDF_VERSION            <- ${{ parameters.version }}  [required]
# Outputs: modifiedJarPath (output), parentGroupId (output), parentArtifactId (output), parentVersion (output), projectGroupId (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_ARTIFACTS_DIR=$(ci_pipeline_workspace)/mule-artifacts}"
: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_BG_ID=}"
: "${MDF_CLASSIFIER=mule-application}"
: "${MDF_DEPLOYMENT_TARGET=ch2}"
: "${MDF_ENV_SETTINGS_PATH?MDF_ENV_SETTINGS_PATH is required (Azure parameter envSettingsPath)}"
: "${MDF_MULE_ENV?MDF_MULE_ENV is required (Azure parameter muleEnv)}"
: "${MDF_VERSION?MDF_VERSION is required (Azure parameter version)}"

# >>> extracted body
ARTIFACT_ID="${MDF_ARTIFACT_ID}"
VERSION="${MDF_VERSION}"
CLASSIFIER="${MDF_CLASSIFIER}"
ENV_SETTINGS_PATH="$(ci_pipeline_workspace)/s/${MDF_ENV_SETTINGS_PATH}"
MULE_ENV="${MDF_MULE_ENV}"
DEPLOYMENT_TARGET="${MDF_DEPLOYMENT_TARGET}"
ARTIFACTS_DIR="${MDF_ARTIFACTS_DIR}"
BG_ID="${MDF_BG_ID}"

JAR_FILE="$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar"
EXTRACT_DIR="$ARTIFACTS_DIR/extracted"
MODIFIED_JAR="$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}-modified.jar"
APP_NAME="$(ci_repo_name)"

echo "[DEBUG] ============================================"
echo "[DEBUG] PRE-DEPLOY TRANSFORMATION START"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   artifactId=$ARTIFACT_ID"
echo "[DEBUG]   version=$VERSION"
echo "[DEBUG]   classifier=$CLASSIFIER"
echo "[DEBUG]   envSettingsPath=$ENV_SETTINGS_PATH"
echo "[DEBUG]   muleEnv=$MULE_ENV"
echo "[DEBUG]   deploymentTarget=$DEPLOYMENT_TARGET"
echo "[DEBUG]   artifactsDir=$ARTIFACTS_DIR"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   appName=$APP_NAME"
echo "[DEBUG] Computed paths:"
echo "[DEBUG]   JAR_FILE=$JAR_FILE"
echo "[DEBUG]   EXTRACT_DIR=$EXTRACT_DIR"
echo "[DEBUG]   MODIFIED_JAR=$MODIFIED_JAR"
echo "[DEBUG] ============================================"

echo "Pre-Deploy transformation for environment: $MULE_ENV"
echo "  Artifact: $JAR_FILE"
echo "  Env Settings: $ENV_SETTINGS_PATH"
echo "  Deployment Target: $DEPLOYMENT_TARGET"

if [[ ! -f "$JAR_FILE" ]]; then
  echo "[DEBUG] File existence check FAILED for: $JAR_FILE"
  echo "[DEBUG] Listing artifacts dir: $(ls -la $ARTIFACTS_DIR 2>&1)"
  ci_log_error "JAR file not found: $JAR_FILE"
  exit 1
fi
echo "[DEBUG] JAR file found. Size: $(stat -f%z "$JAR_FILE" 2>/dev/null || stat --printf="%s" "$JAR_FILE" 2>/dev/null) bytes"

# Step 1: Unzip JAR
echo "[DEBUG] Step 1: Extracting JAR..."
rm -rf "$EXTRACT_DIR"
mkdir -p "$EXTRACT_DIR"
unzip -o "$JAR_FILE" -d "$EXTRACT_DIR" > /dev/null
echo "[DEBUG] Extracted files count: $(find "$EXTRACT_DIR" -type f | wc -l)"
echo "[DEBUG] Extracted directory structure (top-level):"
echo "[DEBUG]   $(ls "$EXTRACT_DIR")"

# Step 2: Replace env config files with environment-specific versions
# Copies env.yaml and env-secure.yaml from the env-settings repo directly
# into the extracted JAR, replacing the existing files at their original paths.
ENV_YAML="$ENV_SETTINGS_PATH/$APP_NAME/env.yaml"
ENV_SECURE_YAML="$ENV_SETTINGS_PATH/$APP_NAME/env-secure.yaml"
SETTINGS_FILE="$ENV_SETTINGS_PATH/$APP_NAME/settings.properties"

echo "[DEBUG] Step 2: Direct file replacement"
echo "[DEBUG]   ENV_YAML source=$ENV_YAML (exists=$([ -f "$ENV_YAML" ] && echo 'yes' || echo 'no'))"
echo "[DEBUG]   ENV_SECURE_YAML source=$ENV_SECURE_YAML (exists=$([ -f "$ENV_SECURE_YAML" ] && echo 'yes' || echo 'no'))"
echo "[DEBUG]   SETTINGS_FILE source=$SETTINGS_FILE (exists=$([ -f "$SETTINGS_FILE" ] && echo 'yes' || echo 'no'))"

# Fail fast on invalid env.yaml in mule-app-env-settings.
# Deployment uses replacement semantics, so empty/incomplete env.yaml can break runtime startup.
if [[ ! -f "$ENV_YAML" ]]; then
  ci_log_error "Missing env.yaml in env-settings: $ENV_YAML"
  exit 1
fi
NON_COMMENT_LINES=$(grep -cvE '^\s*(#|$)' "$ENV_YAML" || true)
if [[ "${NON_COMMENT_LINES:-0}" -eq 0 ]]; then
  ci_log_error "env.yaml is empty or comment-only: $ENV_YAML"
  ci_log_error "Pre-deploy replaces env.yaml in the JAR; an empty file will break deployment."
  exit 1
fi

IS_API_MANAGER="true"
if [[ -f "$SETTINGS_FILE" ]]; then
  IS_API_MANAGER=$(grep '^is\.api\.manager=' "$SETTINGS_FILE" | cut -d'=' -f2- | tr -d '[:space:]' | tr '[:upper:]' '[:lower:]')
  [[ -z "$IS_API_MANAGER" ]] && IS_API_MANAGER="true"
fi
if [[ "$IS_API_MANAGER" == "true" ]]; then
  if ! grep -qE '(^|[[:space:]])autodiscoveryID[[:space:]]*:' "$ENV_YAML"; then
    ci_log_error "is.api.manager=true but env.yaml has no api.autodiscoveryID value block."
    ci_log_error "Either add autodiscoveryID in env.yaml or set is.api.manager=false in settings.properties."
    exit 1
  fi
fi

# Replace env.yaml inside the extracted JAR
if [[ -f "$ENV_YAML" ]]; then
  TARGET_ENV_YAML=$(find "$EXTRACT_DIR" -type f -name "env.yaml" | head -1)
  if [[ -n "$TARGET_ENV_YAML" ]]; then
    echo "Replacing env.yaml at: ${TARGET_ENV_YAML#$EXTRACT_DIR/}"
    echo "[DEBUG]   Source: $ENV_YAML"
    echo "[DEBUG]   Target: $TARGET_ENV_YAML"
    cp "$ENV_YAML" "$TARGET_ENV_YAML"
  else
    ci_log_warning "env.yaml not found inside JAR. Skipping replacement."
    echo "[DEBUG] No env.yaml found in extracted JAR structure"
  fi
else
  ci_log_warning "env.yaml not found at: $ENV_YAML"
fi

# Replace env-secure.yaml inside the extracted JAR
if [[ -f "$ENV_SECURE_YAML" ]]; then
  # Validate: reject scalar values that are not in ![...] encrypted format.
  # Implemented in awk (not a python heredoc): a heredoc body sits at
  # column 0, which terminates the enclosing YAML 'script: |' block scalar
  # and makes the pipeline fail to COMPILE. awk keeps the check inline and
  # indented within the block. Handles both quoted and unquoted scalars,
  # skips comments / blanks / empty values / inline-comment-only values.
  PLAINTEXT_LINES=$(awk '
    /^[[:space:]]*#/ { next }
    /^[[:space:]]*$/ { next }
    !/:/ { next }
    {
      val = $0; sub(/^[^:]*:/, "", val)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", val)
      if (val == "") next
      if (val ~ /^#/) next
      if (val ~ /^".*"$/)      { val = substr(val, 2, length(val) - 2) }
      else if (val ~ /^'"'"'.*'"'"'$/) { val = substr(val, 2, length(val) - 2) }
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", val)
      if (val !~ /^!\[.*\]$/) print NR ":" $0
    }
  ' "$ENV_SECURE_YAML")
  if [[ -n "$PLAINTEXT_LINES" ]]; then
    ci_log_error "env-secure.yaml contains values not in encrypted format."
    ci_log_error "All values must use the ![...] pattern. Offending lines:"
    echo "$PLAINTEXT_LINES"
    ci_log_error "Use the mule-encrypt.py CLI tool or the encrypt-secure-property pipeline to encrypt values."
    exit 1
  fi

  TARGET_ENV_SECURE_YAML=$(find "$EXTRACT_DIR" -type f -name "env-secure.yaml" | head -1)
  if [[ -n "$TARGET_ENV_SECURE_YAML" ]]; then
    echo "Replacing env-secure.yaml at: ${TARGET_ENV_SECURE_YAML#$EXTRACT_DIR/}"
    echo "[DEBUG]   Source: $ENV_SECURE_YAML"
    echo "[DEBUG]   Target: $TARGET_ENV_SECURE_YAML"
    cp "$ENV_SECURE_YAML" "$TARGET_ENV_SECURE_YAML"
  else
    ci_log_warning "env-secure.yaml not found inside JAR. Skipping replacement."
    echo "[DEBUG] No env-secure.yaml found in extracted JAR structure"
  fi
else
  echo "No env-secure.yaml found at: $ENV_SECURE_YAML (optional)"
fi

echo "[DEBUG] File replacement complete"

# Step 3: Copy env-specific overlay files if they exist
ENV_OVERLAY_DIR="$ENV_SETTINGS_PATH/$APP_NAME/overlay"
echo "[DEBUG] Step 3: Overlay check"
echo "[DEBUG]   ENV_OVERLAY_DIR=$ENV_OVERLAY_DIR (exists=$([ -d "$ENV_OVERLAY_DIR" ] && echo 'yes' || echo 'no'))"
if [[ -d "$ENV_OVERLAY_DIR" ]]; then
  echo "Applying overlay files from: $ENV_OVERLAY_DIR"
  echo "[DEBUG] Overlay files: $(ls "$ENV_OVERLAY_DIR")"
  cp -r "$ENV_OVERLAY_DIR"/* "$EXTRACT_DIR/" 2>/dev/null || true
fi

# Step 4: Re-JAR
echo "[DEBUG] Step 4: Repackaging JAR..."
(cd "$EXTRACT_DIR" && jar -cf "$MODIFIED_JAR" .)
echo "[DEBUG] Modified JAR size: $(stat -f%z "$MODIFIED_JAR" 2>/dev/null || stat --printf="%s" "$MODIFIED_JAR" 2>/dev/null) bytes"

# Replace original with modified
mv "$MODIFIED_JAR" "$JAR_FILE"
echo "Modified JAR saved: $JAR_FILE"
echo "[DEBUG] PRE-DEPLOY TRANSFORMATION COMPLETE"

# Step 5: Extract parent POM coordinates for deploy-pom.xml
echo "[DEBUG] Step 5: Extracting parent POM GAV from application pom.xml..."
POM_FILE=$(find "$EXTRACT_DIR/META-INF/maven" -name "pom.xml" 2>/dev/null | head -1)
PARENT_GROUP_ID=""
PARENT_ARTIFACT_ID=""
PARENT_VERSION=""

if [[ -n "$POM_FILE" && -f "$POM_FILE" ]]; then
  echo "[DEBUG] Found pom.xml at: $POM_FILE"
  PARENT_BLOCK_XML=$(awk '/<parent>/{found=1} found{print} /<\/parent>/{found=0}' "$POM_FILE")
  if [[ -n "$PARENT_BLOCK_XML" ]]; then
    PARENT_GROUP_ID=$(echo "$PARENT_BLOCK_XML" | grep '<groupId>' | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
    PARENT_ARTIFACT_ID=$(echo "$PARENT_BLOCK_XML" | grep '<artifactId>' | sed 's/.*<artifactId>\(.*\)<\/artifactId>.*/\1/' | tr -d '[:space:]')
    PARENT_VERSION=$(echo "$PARENT_BLOCK_XML" | grep '<version>' | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
  fi
  echo "[DEBUG] Parent POM: ${PARENT_GROUP_ID}:${PARENT_ARTIFACT_ID}:${PARENT_VERSION}"

  # Extract project groupId (skip <parent> block, take first <groupId> after it)
  PARENT_END_LINE=$(grep -n '</parent>' "$POM_FILE" | head -1 | cut -d: -f1)
  if [[ -n "$PARENT_END_LINE" ]]; then
    PROJECT_GROUP_ID=$(tail -n +"$((PARENT_END_LINE + 1))" "$POM_FILE" | grep '<groupId>' | head -1 | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
  else
    PROJECT_GROUP_ID=$(grep '<groupId>' "$POM_FILE" | head -1 | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
  fi
  echo "[DEBUG] Project groupId: ${PROJECT_GROUP_ID}"
else
  echo "[DEBUG] pom.xml not found in extracted JAR — deploy-pom.xml will not have a <parent> block"
  ci_log_warning "pom.xml not found in JAR. Deploy POM will lack parent reference; Maven profiles/plugins may not resolve."
  PROJECT_GROUP_ID=""
fi

# Set output variables
ci_set_var modifiedJarPath "$JAR_FILE"
ci_set_var parentGroupId "$PARENT_GROUP_ID"
ci_set_var parentArtifactId "$PARENT_ARTIFACT_ID"
ci_set_var parentVersion "$PARENT_VERSION"
ci_set_var projectGroupId "$PROJECT_GROUP_ID"
echo "[DEBUG] Output: modifiedJarPath=$JAR_FILE"
echo "[DEBUG] Output: parentGroupId=$PARENT_GROUP_ID, parentArtifactId=$PARENT_ARTIFACT_ID, parentVersion=$PARENT_VERSION"
echo "[DEBUG] Output: projectGroupId=$PROJECT_GROUP_ID"
# <<< extracted body
